import{_ as a,y as o,a as s,o as i,a2 as t,D as n}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Generative AI Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configure/magic-ai.md","filePath":"configure/magic-ai.md","lastUpdated":1789383309000}'),g={name:"configure/magic-ai.md"};function h(l,e,d,c,u,f){const r=o("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="generative-ai-configuration" tabindex="-1">Generative AI Configuration <a class="header-anchor" href="#generative-ai-configuration" aria-label="Permalink to &quot;Generative AI Configuration&quot;">​</a></h1><p>Bagisto&#39;s generative AI features are branded <strong>Magic AI</strong> in the admin, and they are all configured in one place: <strong>Configure &gt;&gt; Magic AI</strong>. The group has four pages, listed on the left: <strong>General</strong>, <strong>Providers</strong>, <strong>Admin Features</strong> and <strong>Storefront Features</strong>.</p><p>This page covers the configuration only. What each feature does, and how to use it, is described in the <a href="./../generative-ai/introduction.html">Generative AI</a> section.</p>',3)),n(r,{src:"/images/configure/magic.png",alt:"Magic AI configuration"}),e[1]||(e[1]=t('<h2 id="turn-generative-ai-on" tabindex="-1">Turn generative AI on <a class="header-anchor" href="#turn-generative-ai-on" aria-label="Permalink to &quot;Turn generative AI on&quot;">​</a></h2><ol><li>Open the <strong>General</strong> page.</li><li>In the <strong>Settings</strong> section, switch <strong>Enabled</strong> on. This is the master switch: the admin features, AI image search and the checkout message do not run until it is on. Review translation is governed by its own switch alone.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',2)),n(r,{src:"/images/configure/general-setting.png",alt:"Magic AI General settings"}),e[2]||(e[2]=t('<h2 id="connect-a-provider" tabindex="-1">Connect a provider <a class="header-anchor" href="#connect-a-provider" aria-label="Permalink to &quot;Connect a provider&quot;">​</a></h2><p>Bagisto ships with eight providers: <strong>OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek, Mistral</strong> and <strong>Ollama</strong>. You only need to connect the ones you plan to use.</p><ol><li>Create an API key in your account on the provider&#39;s website.</li><li>Open the <strong>Providers</strong> page.</li><li>Paste the key into that provider&#39;s <strong>API Key</strong> field.</li><li>For <strong>Ollama</strong>, which runs models on your own server, enter the <strong>Base URL</strong> of that server as well, for example <code>http://localhost:11434</code>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>Keys are stored as passwords and are not shown again once saved.</p>',4)),n(r,{src:"/images/configure/providers-magicai.png",alt:"Magic AI Providers section"}),e[3]||(e[3]=t('<h2 id="enable-the-admin-features" tabindex="-1">Enable the admin features <a class="header-anchor" href="#enable-the-admin-features" aria-label="Permalink to &quot;Enable the admin features&quot;">​</a></h2><p>Two features help you while you work in the admin: <strong>Text Generation</strong>, described under <a href="./../generative-ai/generate-content.html">Generate text content</a>, and <strong>Image Generation</strong>, described under <a href="./../generative-ai/generate-images.html">Generate product images</a>.</p><ol><li>Open the <strong>Admin Features</strong> page.</li><li>In the <strong>Text Generation</strong> section, switch <strong>Enabled</strong> on.</li><li>In <strong>Providers</strong>, pick the providers whose models admins may use for text. Only providers with a saved key are useful here.</li><li>Repeat the two steps in the <strong>Image Generation</strong> section. Not every provider offers image models.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),n(r,{src:"/images/configure/admin-features-magicai.png",alt:"Magic AI Admin Features section"}),e[4]||(e[4]=t('<h2 id="enable-the-storefront-features" tabindex="-1">Enable the storefront features <a class="header-anchor" href="#enable-the-storefront-features" aria-label="Permalink to &quot;Enable the storefront features&quot;">​</a></h2><p>Three features run on the storefront: <strong>AI Image Search</strong>, <strong>Review Translation</strong> and <strong>Personalized Checkout Message</strong>. Each is set <strong>per channel</strong>; when your store has more than one channel, choose the channel at the top of the page first.</p><ol><li>Open the <strong>Storefront Features</strong> page.</li><li>In the <strong>AI Image Search</strong>, <strong>Review Translation</strong> and <strong>Personalized Checkout Message</strong> sections, switch <strong>Enabled</strong> on for each feature you want.</li><li>Choose the <strong>Model</strong> each feature runs on. Only models of providers with a saved key work.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),n(r,{src:"/images/configure/storefront-features-magicai.png",alt:"Magic AI Storefront Features section"}),e[5]||(e[5]=t('<p>AI image search also needs the storefront&#39;s image search switched on under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>; see <a href="./../generative-ai/image-search.html">AI image search</a>.</p><h2 id="where-each-setting-takes-effect" tabindex="-1">Where each setting takes effect <a class="header-anchor" href="#where-each-setting-takes-effect" aria-label="Permalink to &quot;Where each setting takes effect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it turns on</th><th>Read more</th></tr></thead><tbody><tr><td><strong>Admin Features &gt;&gt; Text Generation</strong></td><td>The <strong>Magic AI</strong> button in every rich-text editor in the admin</td><td><a href="./../generative-ai/generate-content.html">Generate text content</a></td></tr><tr><td><strong>Admin Features &gt;&gt; Image Generation</strong></td><td>The <strong>Magic AI</strong> button beside <strong>Add Image</strong> in the image uploader</td><td><a href="./../generative-ai/generate-images.html">Generate product images</a></td></tr><tr><td><strong>Storefront Features &gt;&gt; AI Image Search</strong></td><td>AI analysis of the photo a shopper searches with</td><td><a href="./../generative-ai/image-search.html">AI image search</a></td></tr><tr><td><strong>Storefront Features &gt;&gt; Review Translation</strong></td><td>The <strong>Translate</strong> link under each product review</td><td><a href="./../generative-ai/review-translation.html">Review translation</a></td></tr><tr><td><strong>Storefront Features &gt;&gt; Personalized Checkout Message</strong></td><td>The message written for each order on the confirmation page</td><td><a href="./../generative-ai/checkout-message.html">Personalized checkout message</a></td></tr></tbody></table>',3))])}const _=a(g,[["render",h]]);export{p as __pageData,_ as default};
